import {CREW,STORY,activeCrew,onDuty,crewCapacity,stats,cargoUsed,hasIllegal,clamp,addLog,systemById} from './world.js';
export const INTRO_SHOTS=[
 {duration:8,label:'THE OUTER REACH / SIX HOURS EARLIER',title:'A shipment of medicine.',who:'Relief carrier · Good Fortune',text:'This is a civilian convoy. Twelve families, clinic supplies. Our clearance is valid.'},
 {duration:8,label:'DIRECTORATE CHECKPOINT / BELLWETHER',title:'An order to stop.',who:'Directorate control',text:'Relief authorization revoked. Cut your drives. Any ship leaving formation will be treated as hostile.'},
 {duration:8,label:'AN OPEN CHANNEL / THEN SILENCE',title:'One ship gets away.',who:'Clinic transport · Mayflower',text:'They fired on the carrier. We lost our drive getting clear. If anyone can hear us… the children need those antibiotics.'},
 {duration:9,label:'MERCY ANCHORAGE / BERTH 04',title:'One captain can answer.',who:'Ada Mercer',text:'I kept Cinder out of impound. Help me bring that convoy home and the cooperative clears your repair lien. You get your ship. They get a tomorrow.'}
];
export const INTRO_DURATION=INTRO_SHOTS.reduce((n,s)=>n+s.duration,0);
export function introFrame(time){let start=0;for(let index=0;index<INTRO_SHOTS.length;index++){const shot=INTRO_SHOTS[index];if(time<start+shot.duration||index===INTRO_SHOTS.length-1)return {...shot,index,start,progress:clamp((time-start)/shot.duration,0,1)};start+=shot.duration;}}
export const BRIEFINGS=[
 {who:'Ada Mercer',role:'Mercy cooperative / your sponsor',title:'A ship worth keeping.',paragraphs:['Cinder was three days from impound when I covered the yard bill. Fourteen thousand eight hundred credits. I do not need another ship, Captain. I need someone who will answer a call.','The Directorate stopped our relief convoy above Bellwether. A clinic transport slipped away with a dead drive and children aboard. The medicine is here. They are out there.','Take the antibiotics to Mayflower. After that, we find the rest of the convoy. Every leg you finish clears part of the repair lien. At the end, Cinder belongs to you.'],question:'What do you need from me?',answer:'A pilot who can get close, stay calm and hold a supply transfer. Jump to Bellwether, approach Mayflower, brake below 45 m/s and hold Transfer. Raiders are already circling.'},
 {who:'Iona Reed',role:'Freight lanes / a name from the recorder',title:'The convoy did not scatter by accident.',paragraphs:['Mayflower’s captain saw a Directorate frigate mark the convoy before the raiders arrived. Someone sold the route.','The miners at Kiln Nine have scrubber parts the survivors need. Old Promise can carry them, but she cannot fight. Stay with her through the belt.'],question:'Why protect this freighter?',answer:'Her crew kept the survivors breathing when their life support failed. We owe them a route out.'},
 {who:'Len Price',role:'Kiln Nine / salvage contact',title:'Ships do not vanish without a trace.',paragraphs:['Old Promise made it. Her mechanic pulled a convoy identifier from the raiders’ comms. It points to the wrecks at Hush.','Read the three black boxes. If those recorders still work, we can prove who gave the order to fire. Somebody will want them quiet.'],question:'Are there survivors?',answer:'The emergency pods left before the last recorder failed. Find the recorders and we may find where the pods went.'},
 {who:'Silas Finch',role:'Relief network / former inner-world medic',title:'The order has a signature.',paragraphs:['The black boxes name Directorate officials. The public story calls the convoy smugglers. Those recordings tell a different one.','A journalist’s shuttle can carry the evidence out of Crown. Follow the shadow lane and transfer the sealed packet. A customs scan will confiscate it.'],question:'What happens if we publish it?',answer:'The officials lose their cover. The relief network gains enough attention to move the survivors. Your registry may take the blame first.'},
 {who:'Ada Mercer',role:'Mercy cooperative / urgent channel',title:'Now they know your name.',paragraphs:['The evidence is out. Families across the Reach are watching. The people who ordered the seizure hired a blockade to finish the job.','Icebound is holding beyond Last Lantern with the survivors aboard. Break the raider attack before they breach her hull. This is the convoy we have been looking for.'],question:'Will the Directorate help?',answer:'Some captains might. The officials who signed the order will not. We cannot wait for them to decide.'},
 {who:'Ada Mercer',role:'Mercy Anchorage / homebound clearance',title:'Bring them home.',paragraphs:['Icebound is clear. Good Fortune has the families aboard for the last leg to Juniper. One raider wing is waiting in the outer approach.','Get those people home. The cooperative has agreed: the last of Cinder’s lien comes off when that ship reaches the beacon. Your name goes on the registration.'],question:'And after that?',answer:'After that you decide where home is. A new ship, a bigger crew, another horizon. For tonight, an empty chair at your own table is enough.'}
];
